// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address callerAsAddr) public {
        vm.assume(callerAsAddr != address(0));
        vm.assume(callerAsAddr != address(this));

        HonestBank bank = new HonestBank();

        vm.prank(address(bank));
        bool ok;
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && c.tokenBalance(address(bank)) == 20);
    }
}

contract HonestBank {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
